/**
 * Outline reorder (builder-design §2, task B3): turn a gesture (drag, Alt+↑/↓, "Move to…")
 * into `move_question` / `move_page` / `move_block` ops, one transaction per gesture.
 * Pure: works on the display tree (blocks → pages → questions) and knows no survey rules
 * beyond the op signatures. The server validates (e.g. a page may not be left empty).
 *
 * Op indices are "position in the destination after removal", applied in order, so ops
 * are generated by simulating each move on a copy of the id lists.
 */
import type { Invocation } from '../sync/transport';
import type { NodeType, OutlineNode } from '../model/outline';

export type MovableType = 'block' | 'page' | 'question';

/**
 * Where moved items go: a gap in `parent`'s children *as they are now* (0..n). `parent`
 * is a block id (pages), a page id (questions) or null (blocks).
 */
export interface DropTarget {
	parent: string | null;
	slot: number;
}

/** Ids by parent: null → block ids, block id → page ids, page id → question ids. */
type Lists = Map<string | null, string[]>;

interface Info {
	type: NodeType;
	parent: string | null;
	label: string;
}

/** Index of every node: its type, parent and label. */
export function indexTree(roots: readonly OutlineNode[]): Map<string, Info> {
	const out = new Map<string, Info>();
	const walk = (nodes: readonly OutlineNode[], parent: string | null) => {
		for (const n of nodes) {
			out.set(n.id, { type: n.type, parent, label: n.label });
			if (n.children) walk(n.children, n.id);
		}
	};
	walk(roots, null);
	return out;
}

function listsOf(roots: readonly OutlineNode[]): Lists {
	const out: Lists = new Map([[null, roots.map((b) => b.id)]]);
	const walk = (nodes: readonly OutlineNode[]) => {
		for (const n of nodes) {
			if (n.type === 'question') continue;
			out.set(n.id, (n.children ?? []).map((c) => c.id));
			if (n.children) walk(n.children);
		}
	};
	walk(roots);
	return out;
}

/** Ids in document (display) order. */
export function docOrder(roots: readonly OutlineNode[]): string[] {
	const out: string[] = [];
	const walk = (nodes: readonly OutlineNode[]) => {
		for (const n of nodes) {
			out.push(n.id);
			if (n.children) walk(n.children);
		}
	};
	walk(roots);
	return out;
}

/** The items a gesture moves: those of `type`, deduplicated, in document order. */
export function movableIds(roots: readonly OutlineNode[], ids: Iterable<string>, type?: MovableType): string[] {
	const idx = indexTree(roots);
	const want = new Set(ids);
	const first = docOrder(roots).find((id) => want.has(id));
	const t = type ?? (first ? idx.get(first)?.type : undefined);
	if (t !== 'block' && t !== 'page' && t !== 'question') return [];
	return docOrder(roots).filter((id) => want.has(id) && idx.get(id)?.type === t);
}

/** The type of children `parent` holds (null → blocks). */
function childType(idx: Map<string, Info>, parent: string | null): MovableType | undefined {
	if (parent === null) return 'block';
	const t = idx.get(parent)?.type;
	return t === 'block' ? 'page' : t === 'page' ? 'question' : undefined;
}

function opFor(type: MovableType, id: string, parent: string | null, index: number): Invocation {
	if (type === 'question') return { op: 'move_question', params: { id, page: parent, index } };
	if (type === 'page') return { op: 'move_page', params: { id, block: parent, index } };
	return { op: 'move_block', params: { id, index } };
}

/**
 * The ops that move `ids` (all one type) into the gap `target`, keeping their document
 * order, as one transaction. Items already in place produce no op; [] if nothing moves
 * or the target can't hold them.
 */
export function moveOps(roots: readonly OutlineNode[], ids: readonly string[], target: DropTarget): Invocation[] {
	const idx = indexTree(roots);
	const moving = movableIds(roots, ids);
	if (!moving.length) return [];
	const type = idx.get(moving[0])!.type as MovableType;
	if (childType(idx, target.parent) !== type) return [];
	const lists = listsOf(roots);
	const dest = lists.get(target.parent) ?? [];
	const set = new Set(moving);
	// The first item lands before the first unmoved item at or after the gap.
	const anchor = dest.slice(Math.max(0, target.slot)).find((id) => !set.has(id)) ?? null;
	const ops: Invocation[] = [];
	let prev: string | null = null;
	for (const id of moving) {
		const from = idx.get(id)!.parent;
		const src = lists.get(from)!;
		const at = src.indexOf(id);
		src.splice(at, 1);
		const d = lists.get(target.parent)!;
		const index = prev !== null ? d.indexOf(prev) + 1 : anchor !== null ? d.indexOf(anchor) : d.length;
		d.splice(index, 0, id);
		idx.set(id, { ...idx.get(id)!, parent: target.parent });
		prev = id;
		if (from === target.parent && at === index) continue;
		ops.push(opFor(type, id, target.parent, index));
	}
	return ops;
}

/**
 * The display tree after `ops` (move ops only; others are ignored). Used for the
 * optimistic outline while the server has not answered.
 */
export function applyMoves(roots: readonly OutlineNode[], ops: readonly Invocation[]): OutlineNode[] {
	const nodes = new Map<string, OutlineNode>();
	const lists = listsOf(roots);
	const idx = indexTree(roots);
	const walk = (ns: readonly OutlineNode[]) => {
		for (const n of ns) {
			nodes.set(n.id, n);
			if (n.children) walk(n.children);
		}
	};
	walk(roots);
	for (const { op, params = {} } of ops) {
		const id = params.id;
		if (typeof id !== 'string' || !idx.has(id)) continue;
		const parent =
			op === 'move_question' ? params.page : op === 'move_page' ? params.block : op === 'move_block' ? null : undefined;
		if (parent === undefined || (parent !== null && typeof parent !== 'string')) continue;
		const dest = lists.get(parent);
		if (!dest) continue;
		const src = lists.get(idx.get(id)!.parent)!;
		src.splice(src.indexOf(id), 1);
		const index = typeof params.index === 'number' ? Math.min(params.index, dest.length) : dest.length;
		dest.splice(index, 0, id);
		idx.set(id, { ...idx.get(id)!, parent });
	}
	const build = (ids: readonly string[]): OutlineNode[] =>
		ids.map((id) => {
			const n = nodes.get(id)!;
			return n.type === 'question' ? n : { ...n, children: build(lists.get(id) ?? []) };
		});
	return build(lists.get(null) ?? []);
}

/**
 * Alt+↑/↓ (and with Shift, across a page or block boundary): where the selected items go,
 * or null at an edge. Plain: past the previous/next sibling. Across: to the end of the
 * previous parent (↑) or the start of the next one (↓); blocks have no boundary to cross.
 */
export function keyboardTarget(
	roots: readonly OutlineNode[],
	ids: readonly string[],
	dir: -1 | 1,
	across: boolean
): DropTarget | null {
	const moving = movableIds(roots, ids);
	if (!moving.length) return null;
	const idx = indexTree(roots);
	const lists = listsOf(roots);
	const set = new Set(moving);
	const lead = dir < 0 ? moving[0] : moving[moving.length - 1];
	const parent = idx.get(lead)!.parent;
	const type = idx.get(lead)!.type;
	if (!across) {
		const sibs = lists.get(parent)!;
		const at = sibs.indexOf(lead);
		if (dir < 0) {
			for (let i = at - 1; i >= 0; i--) if (!set.has(sibs[i])) return { parent, slot: i };
		} else {
			for (let i = at + 1; i < sibs.length; i++) if (!set.has(sibs[i])) return { parent, slot: i + 1 };
		}
		// Already at the edge of its parent; if the selection is split, gather it there.
		const gathered = moveOps(roots, moving, { parent, slot: dir < 0 ? 0 : sibs.length });
		return gathered.length ? { parent, slot: dir < 0 ? 0 : sibs.length } : null;
	}
	if (type === 'block' || parent === null) return null;
	// Parents of this kind (pages or blocks), in document order.
	const parents = docOrder(roots).filter((id) => idx.get(id)?.type === idx.get(parent)?.type);
	const next = parents[parents.indexOf(parent) + dir];
	if (next === undefined) return null;
	return { parent: next, slot: dir < 0 ? lists.get(next)!.length : 0 };
}

/** Where `id` ends up after the ops: its parent and 1-based position, for announcements. */
export function positionAfter(
	roots: readonly OutlineNode[],
	ops: readonly Invocation[],
	id: string
): { parent: OutlineNode | null; position: number; of: number } | null {
	const after = applyMoves(roots, ops);
	const idx = indexTree(after);
	const info = idx.get(id);
	if (!info) return null;
	const find = (ns: readonly OutlineNode[]): OutlineNode | null => {
		for (const n of ns) {
			if (n.id === info.parent) return n;
			const hit = n.children && find(n.children);
			if (hit) return hit;
		}
		return null;
	};
	const parent = info.parent === null ? null : find(after);
	const sibs = parent ? (parent.children ?? []) : after;
	return { parent, position: sibs.findIndex((n) => n.id === id) + 1, of: sibs.length };
}

/** "Moved X to position 2 of 3 in Page 1" / "Moved 3 questions to …". */
export function describeMove(roots: readonly OutlineNode[], ops: readonly Invocation[], ids: readonly string[]): string {
	const idx = indexTree(roots);
	const first = ids[0];
	const pos = first ? positionAfter(roots, ops, first) : null;
	if (!first || !pos) return 'Moved.';
	const type = idx.get(first)?.type ?? 'item';
	const what = ids.length === 1 ? (idx.get(first)?.label ?? first) : `${ids.length} ${type}s`;
	const where = pos.parent ? ` in ${pos.parent.label}` : '';
	return `Moved ${what} to position ${pos.position} of ${pos.of}${where}`;
}

/** Destinations for "Move to…": every parent that can hold `type`, with a readable name. */
export function destinations(
	roots: readonly OutlineNode[],
	type: MovableType
): { parent: string | null; label: string; size: number; children: OutlineNode[] }[] {
	if (type === 'block') return [{ parent: null, label: 'Survey', size: roots.length, children: [...roots] }];
	if (type === 'page') {
		return roots.map((b) => ({ parent: b.id, label: b.label, size: b.children?.length ?? 0, children: b.children ?? [] }));
	}
	return roots.flatMap((b) =>
		(b.children ?? []).map((p) => ({
			parent: p.id,
			label: `${p.label} (${b.label})`,
			size: p.children?.length ?? 0,
			children: p.children ?? []
		}))
	);
}
